import {HelpCircle} from "lucide-react";
import i18next from "i18next";

import {cn} from "@/lib/utils";
import {formatScore, gradeLetter, gradeRanges, gradeStyleOf, gradeStyles} from "@/lib/authenticity";
import {Badge} from "@/components/ui/badge";
import {SimpleTooltip} from "@/components/ui/tooltip";
import type {ProbeGrade, ProviderProbe} from "@/types";

/**
 * Which score buys which letter. A letter on its own is a verdict nobody can
 * check, so the scale sits behind the question mark next to every grade.
 */
export function GradeScaleTip({className}: {className?: string}) {
  return (
    <SimpleTooltip
      className="max-w-xs"
      title={
        <div className="flex flex-col gap-1">
          <span className="font-medium">{i18next.t("audit:How a score becomes a letter")}</span>
          {gradeRanges().map(entry => (
            <div key={entry.grade} className="flex items-center gap-2">
              <span className="w-3 shrink-0 font-semibold">{entry.grade}</span>
              <span className="w-14 shrink-0 tabular-nums opacity-80">{`${entry.low}–${entry.high}`}</span>
              <span>{i18next.t(gradeStyles[entry.grade].label)}</span>
            </div>
          ))}
          <span className="opacity-80">{i18next.t("audit:Score is the weighted share")}</span>
        </div>
      }
    >
      <HelpCircle
        className={cn("text-muted-foreground size-3.5 shrink-0 cursor-help", className)}
        aria-label={i18next.t("audit:How a score becomes a letter")}
      />
    </SimpleTooltip>
  );
}

/**
 * The score as a dial. The number is the weighted share of the test cases that
 * could be measured which answered the way the vendor's own API documents, so
 * the ring is drawn over the same 0-100 the letter is cut from.
 */
export function ScoreDial({
  probe,
  size = 92,
  className,
}: {
  probe?: ProviderProbe;
  size?: number;
  className?: string;
}) {
  const grade: ProbeGrade = probe?.ok ? probe.grade : "unknown";
  const style = gradeStyleOf(grade);
  const measured = grade !== "unknown";
  const share = measured ? Math.max(0, Math.min(100, probe?.score ?? 0)) / 100 : 0;

  const stroke = Math.max(6, Math.round(size / 12));
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;

  // Everything written here has to fit the square that fits inside the ring,
  // which is what a small dial has no room for: it carries the letter alone
  // rather than pushing "Grade A" out under the stroke.
  const inner = (size - 2 * stroke) / Math.SQRT2;
  const letter = gradeLetter(grade);
  const label = `${i18next.t("audit:Grade")} ${letter}`;
  const labelSize = Math.max(9, size / 8);
  const spelled = label.length * labelSize * 0.62 <= inner;

  return (
    <div className={cn("relative shrink-0", className)} style={{width: size, height: size}}>
      <svg width={size} height={size} className="-rotate-90">
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          strokeWidth={stroke}
          className="stroke-muted"
        />
        <circle
          cx={size / 2}
          cy={size / 2}
          r={radius}
          fill="none"
          strokeWidth={stroke}
          strokeLinecap="round"
          strokeDasharray={`${circumference * share} ${circumference}`}
          className={cn("transition-[stroke-dasharray] duration-500", style.ring)}
          stroke="currentColor"
        />
      </svg>
      {/* The ring is the one thing here that takes the grade's colour; the
          number inside it is ordinary text. */}
      <div className="absolute inset-0 flex flex-col items-center justify-center gap-1">
        <span
          className="font-semibold tabular-nums leading-none"
          style={{fontSize: size / 3.8}}
        >
          {formatScore(probe)}
        </span>
        {spelled || measured ? (
          <span
            className="text-muted-foreground font-medium tracking-wide uppercase leading-none"
            style={{fontSize: labelSize}}
          >
            {spelled ? label : letter}
          </span>
        ) : null}
      </div>
    </div>
  );
}

/**
 * The same finding in one line, for a card that has no room for a dial. It
 * always says what it means: a provider nobody could measure reads as
 * unmeasured rather than as passing.
 */
export function ScoreBadge({
  probe,
  showLabel = true,
  className,
}: {
  probe?: ProviderProbe;
  showLabel?: boolean;
  className?: string;
}) {
  const grade: ProbeGrade = probe?.ok ? probe.grade : "unknown";
  const style = gradeStyleOf(grade);
  const title = probe
    ? `${i18next.t(style.label)} · ${i18next.t(style.verdict)}`
    : i18next.t("audit:Not probed yet");

  return (
    <SimpleTooltip title={title}>
      <Badge variant="outline" className={cn("gap-1.5 font-medium", style.badge, className)}>
        <span className="tabular-nums">
          {gradeLetter(grade)}
          {grade === "unknown" ? "" : ` · ${formatScore(probe)}`}
        </span>
        {showLabel ? <span className="hidden sm:inline">{i18next.t(style.label)}</span> : null}
      </Badge>
    </SimpleTooltip>
  );
}

