@custom-variant dark (&:is(.dark *));

/* "Amber & Ink". The palette comes off the casbin mark: the orange star is the
   primary, the shield green is success, the gopher blue is info. Nothing here
   is a true neutral — every grey carries a warm hue, so the page reads as paper
   and ink rather than as a default component library. */
:root {
  --radius: 0.5rem;

  /* Paper, with the card lifted a shade above it: that gap is most of the
     layering the page needs, so panels can stay nearly shadowless. */
  --background: oklch(0.974 0.010 83);
  --foreground: oklch(0.205 0.014 60);
  --card: oklch(0.999 0.003 85);
  --card-foreground: oklch(0.205 0.014 60);
  --popover: oklch(0.999 0.003 85);
  --popover-foreground: oklch(0.205 0.014 60);

  /* Deep enough to serve as link ink and as a button fill under white. */
  --primary: oklch(0.545 0.155 48);
  --primary-foreground: oklch(0.99 0.012 90);
  --secondary: oklch(0.955 0.014 78);
  --secondary-foreground: oklch(0.30 0.024 55);
  --muted: oklch(0.957 0.011 78);
  --muted-foreground: oklch(0.505 0.020 62);
  --accent: oklch(0.945 0.028 70);
  --accent-foreground: oklch(0.33 0.050 48);

  /* Held apart from --primary by hue and chroma, not by lightness alone: these
     are ink for a word or a dot and often sit in the same row as a link. */
  --destructive: oklch(0.545 0.205 25);
  --destructive-foreground: oklch(0.99 0.012 90);
  --success: oklch(0.505 0.125 150);
  --success-foreground: oklch(0.99 0.012 90);
  --warning: oklch(0.545 0.120 90);
  --warning-foreground: oklch(0.99 0.012 90);
  --info: oklch(0.520 0.115 235);
  --info-foreground: oklch(0.99 0.012 90);

  --border: oklch(0.893 0.014 75);
  --input: oklch(0.878 0.016 75);
  --ring: oklch(0.545 0.155 48);

  --chart-1: oklch(0.620 0.155 48);
  --chart-2: oklch(0.580 0.115 200);
  --chart-3: oklch(0.660 0.130 92);
  --chart-4: oklch(0.500 0.115 150);
  --chart-5: oklch(0.520 0.130 300);

  /* The rail is a deeper sheet of the same paper, so it reads as a separate
     surface without needing a heavy border. */
  --sidebar: oklch(0.950 0.016 80);
  --sidebar-foreground: oklch(0.245 0.016 60);
  --sidebar-primary: oklch(0.545 0.155 48);
  --sidebar-primary-foreground: oklch(0.99 0.012 90);
  --sidebar-accent: oklch(0.922 0.032 68);
  --sidebar-accent-foreground: oklch(0.355 0.085 45);
  --sidebar-border: oklch(0.886 0.018 75);
  --sidebar-ring: oklch(0.545 0.155 48);
}

.dark {
  /* Warm charcoal, not neutral black: the same hue the light mode uses for ink. */
  --background: oklch(0.175 0.010 62);
