@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* Inter is never fetched, so the CJK faces are what a zh reader actually
     gets; without them Windows falls back to a mismatched SimSun. */
  --font-sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue",
    "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  --font-mono: "Cascadia Code", "Fira Mono", Consolas, ui-monospace, monospace;
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html, body, #root {
    height: 100%;
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-feature-settings: "rlig" 1, "calt" 1;
  }
  ::selection {
    background-color: color-mix(in oklab, var(--primary) 22%, transparent);
  }
  /* Titles set a touch tighter than the body — at these sizes that tracking is
     most of what separates a heading from bold text. */
  h1, h2, h3, [data-slot="card-title"], [data-slot="dialog-title"] {
    letter-spacing: -0.012em;
  }
  /* Counts, costs and token totals are read down a column, not across a line. */
  table {
    font-variant-numeric: tabular-nums;
  }
}

@layer utilities {
  /* Record payloads, rule expressions and log tails all scroll; a hairline
     scrollbar keeps those panes from being dominated by platform chrome. */
  .scrollbar-thin {
    scrollbar-width: thin;
    scrollbar-color: var(--border) transparent;
  }
  .scrollbar-thin::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  .scrollbar-thin::-webkit-scrollbar-thumb {
    background-color: var(--border);
    border-radius: 4px;
  }
  .scrollbar-thin::-webkit-scrollbar-thumb:hover {
    background-color: color-mix(in oklab, var(--primary) 45%, transparent);
  }
  .scrollbar-thin::-webkit-scrollbar-track {
    background: transparent;
  }
  /* Figures that should line up with each other rather than with prose. */
  .tabular {
    font-variant-numeric: tabular-nums;
  }
}

@keyframes dot-bounce {
  0%, 80%, 100% { transform: scale(0.7); opacity: 0.5; }
  40% { transform: scale(1); opacity: 1; }
}

/* The bar under a running install, for the package managers that report no
   percentage of their own: it says work is happening, not how much is left. */
@keyframes install-sweep {
  0% { left: -40%; }
  100% { left: 100%; }
}
